do $$
declare src text:='https://meslek.meb.gov.tr/upload/cop11_mem/2022_pazarlama_mem_cop.pdf'; b text; bra text[]:=array['Emlak Komisyonculuğu','Satış Elemanlığı','Sigortacılık'];
begin
foreach b in array bra loop
 insert into official_curriculum_profiles(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,required_course_count,required_hour_total,elective_course_min,elective_course_max,elective_hour_min,elective_hour_max,total_hour_min,total_hour_max,total_hour_target,group_rules,source_file_name,source_decision_no,source_note,active,schedule_variant,common_hours,vocational_hours,elective_vocational_hours,elective_hours,guidance_hours,enterprise_hours,applicability_status,source_page,parsed_constraints,academic_support_hours)
 select s.effective_academic_year,s.school_type,s.school_subtype,s.program_type,'Pazarlama ve Perakende',b,s.grade_level,s.required_course_count,s.required_hour_total,s.elective_course_min,s.elective_course_max,s.elective_hour_min,s.elective_hour_max,s.total_hour_min,s.total_hour_max,s.total_hour_target,s.group_rules,src,'2022-33','2022-33 yaşayan MESEM Pazarlama ve Perakende çizelgesi; parantezli temel ders saatleri DIPLOMA fark dersidir.',true,s.schedule_variant,s.common_hours,s.vocational_hours,s.elective_vocational_hours,s.elective_hours,s.guidance_hours,s.enterprise_hours,'CURRENTLY_VALID',case b when 'Emlak Komisyonculuğu' then 8 when 'Satış Elemanlığı' then 9 else 10 end,s.parsed_constraints,s.academic_support_hours
 from official_curriculum_profiles s where s.active and s.school_type='MESEM' and s.field_name='Mobilya ve İç Mekân Tasarımı' and s.branch_name='Ahşap Doğrama Teknolojisi' and not exists(select 1 from official_curriculum_profiles x where x.active and x.effective_academic_year=s.effective_academic_year and x.school_type='MESEM' and coalesce(x.school_subtype,'')=coalesce(s.school_subtype,'') and coalesce(x.program_type,'')=coalesce(s.program_type,'') and x.field_name='Pazarlama ve Perakende' and x.branch_name=b and x.grade_level=s.grade_level and coalesce(x.schedule_variant,'STANDARD')=coalesce(s.schedule_variant,'STANDARD'));
end loop;
insert into course_catalog(name,category,active) select n,'uygulama',true from unnest(array['Pazarlama ve Perakende Temelleri','Standart Türk Klavyesi','Ofis Programları','Çalışma Hayatı','Diksiyon ve Etkili İletişim','Müşteri İlişkileri','Ticari Hesaplamalar','Hukuk','Ahilik Kültürü ve Girişimcilik','Emlak Hizmetleri','Tapu İşlemleri','Emlakçılık Paket Programı','Emlak Gündemi','İnteraktif Emlak Komisyonculuğu','Perakendecilik','Gıda Satışında Hijyen ve Sanitasyon','Stok Kontrol','Kasa İşlemleri','Ürün Alımı ve Satışı','Sigortacılıkta Risk','Hasar','Can-Mal Sigortaları ve Bireysel Emeklilik Sistemi','Sigorta Paket Programı','Sorumluluk Sigortaları','Sigorta Hukuku','Sigorta Acentesi Açılış İşlemleri']) n where not exists(select 1 from course_catalog c where c.name=n);
insert into official_course_schedule_catalog(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,source_decision_no,source_page,parsed_constraints,needs_review,schedule_variant)
select p.effective_academic_year,p.school_type,p.school_subtype,p.program_type,p.field_name,p.branch_name,p.grade_level,s.course_id,s.category,s.hour_options,s.max_selections,s.repeat_across_years,src,p.source_note,true,'2022-33',p.source_page,s.parsed_constraints,false,p.schedule_variant from official_curriculum_profiles p join official_curriculum_profiles sp on sp.active and sp.school_type='MESEM' and sp.field_name='Mobilya ve İç Mekân Tasarımı' and sp.branch_name='Ahşap Doğrama Teknolojisi' and sp.grade_level=p.grade_level and sp.schedule_variant=p.schedule_variant join official_course_schedule_catalog s on s.active and s.school_type='MESEM' and s.field_name='Mobilya ve İç Mekân Tasarımı' and s.branch_name='Ahşap Doğrama Teknolojisi' and s.grade_level=sp.grade_level and s.schedule_variant=sp.schedule_variant join course_catalog c on c.id=s.course_id where p.active and p.school_type='MESEM' and p.field_name='Pazarlama ve Perakende' and (s.category='zorunlu' or c.name='İşletmelerde Mesleki Eğitim') and not exists(select 1 from official_course_schedule_catalog x where x.active and x.effective_academic_year=p.effective_academic_year and x.school_type=p.school_type and coalesce(x.school_subtype,'')=coalesce(p.school_subtype,'') and coalesce(x.program_type,'')=coalesce(p.program_type,'') and coalesce(x.field_name,'')=p.field_name and coalesce(x.branch_name,'')=p.branch_name and x.grade_level=p.grade_level and x.course_id=s.course_id and coalesce(x.schedule_variant,'STANDARD')=coalesce(p.schedule_variant,'STANDARD'));
insert into official_course_schedule_catalog(effective_academic_year,school_type,program_type,field_name,branch_name,grade_level,course_id,category,hour_options,source_file_name,source_note,active,source_decision_no,source_page,parsed_constraints,needs_review,schedule_variant)
select p.effective_academic_year,'MESEM','MESEM','Pazarlama ve Perakende',p.branch_name,p.grade_level,c.id,'uygulama',array[v.h],src,p.source_note,true,'2022-33',p.source_page,'[]'::jsonb,false,p.schedule_variant from official_curriculum_profiles p join lateral (select * from (values (9,'*','Pazarlama ve Perakende Temelleri',2),(10,'*','Standart Türk Klavyesi',1),(10,'*','Ofis Programları',1),(10,'*','Çalışma Hayatı',1),(10,'*','Diksiyon ve Etkili İletişim',1),(11,'*','Müşteri İlişkileri',1),(11,'*','Ticari Hesaplamalar',1),(11,'*','Hukuk',1),(12,'*','Ahilik Kültürü ve Girişimcilik',1),(11,'Emlak Komisyonculuğu','Emlak Hizmetleri',2),(11,'Emlak Komisyonculuğu','Tapu İşlemleri',2),(12,'Emlak Komisyonculuğu','Emlakçılık Paket Programı',2),(12,'Emlak Komisyonculuğu','Emlak Gündemi',2),(12,'Emlak Komisyonculuğu','İnteraktif Emlak Komisyonculuğu',3),(11,'Satış Elemanlığı','Perakendecilik',3),(11,'Satış Elemanlığı','Gıda Satışında Hijyen ve Sanitasyon',1),(12,'Satış Elemanlığı','Stok Kontrol',2),(12,'Satış Elemanlığı','Kasa İşlemleri',2),(12,'Satış Elemanlığı','Ürün Alımı ve Satışı',3),(11,'Sigortacılık','Sigortacılıkta Risk',1),(11,'Sigortacılık','Hasar',1),(11,'Sigortacılık','Can-Mal Sigortaları ve Bireysel Emeklilik Sistemi',2),(12,'Sigortacılık','Sigorta Paket Programı',1),(12,'Sigortacılık','Sorumluluk Sigortaları',2),(12,'Sigortacılık','Sigorta Hukuku',2),(12,'Sigortacılık','Sigorta Acentesi Açılış İşlemleri',2))t(g,br,n,h) where t.g=p.grade_level and (t.br='*' or t.br=p.branch_name)) v on true join course_catalog c on c.name=v.n where p.active and p.school_type='MESEM' and p.field_name='Pazarlama ve Perakende' and not exists(select 1 from official_course_schedule_catalog x where x.active and x.effective_academic_year=p.effective_academic_year and x.school_type='MESEM' and coalesce(x.program_type,'')='MESEM' and coalesce(x.field_name,'')='Pazarlama ve Perakende' and coalesce(x.branch_name,'')=p.branch_name and x.grade_level=p.grade_level and x.course_id=c.id and coalesce(x.schedule_variant,'STANDARD')=coalesce(p.schedule_variant,'STANDARD'));
end $$;